source_format:
{
  "templateId": "bank-interest",
  "templateVersion": 1,
  "title": "Bank Interest",
  "description_template": "Bank interest on {account_number}, {interest_from} to {interest_to}[[ – {bank_name}]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Interest",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "account_number",
          "label": "Bank Account No.",
          "type": "text",
          "required": true
        },
        {
          "key": "interest_from",
          "label": "Interest From",
          "type": "date",
          "required": true
        },
        {
          "key": "interest_to",
          "label": "Interest To",
          "type": "date",
          "required": true
        },
        {
          "key": "bank_name",
          "label": "Bank",
          "type": "text"
        }
      ]
    }
  ]
}

{
  "templateId": "courier-dispatch",
  "templateVersion": 1,
  "title": "Postage & Courier",
  "description_template": "Courier via {courier_partner} – {contents} to {sent_to} on {dispatch_date}[[, AWB {docket_no}]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Dispatch",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "courier_partner",
          "label": "Courier Partner",
          "type": "text",
          "required": true
        },
        {
          "key": "contents",
          "label": "Contents",
          "type": "text",
          "required": true
        },
        {
          "key": "sent_to",
          "label": "Sent To",
          "type": "text",
          "required": true
        },
        {
          "key": "dispatch_date",
          "label": "Dispatch Date",
          "type": "date",
          "required": true
        },
        {
          "key": "docket_no",
          "label": "Docket / AWB No.",
          "type": "text"
        }
      ]
    },
    {
      "id": "proof",
      "type": "image_attachments",
      "title": "Proof",
      "columns": 2,
      "slots": [
        {
          "key": "bill",
          "label": "Receipt",
          "accept": "image/*,application/pdf",
          "maxSizeMb": 5,
          "maps_to": "invoice_attachment"
        }
      ]
    }
  ]
}

{
  "templateId": "travel",
  "templateVersion": 4,
  "title": "Travel",
  "description_template": "{traveller_name} – flight from {from_location} to {to_location} on {depart_date}[[ for {purpose}]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Trip",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "traveller_name",
          "label": "Traveller Name",
          "type": "text",
          "required": true,
          "bind": "user.full_name"
        },
        {
          "key": "purpose",
          "label": "Purpose",
          "type": "text",
          "required": true
        },
        {
          "key": "from_location",
          "label": "From",
          "type": "text",
          "required": true
        },
        {
          "key": "to_location",
          "label": "To",
          "type": "text",
          "required": true
        },
        {
          "key": "depart_date",
          "label": "Departure Date",
          "type": "date",
          "required": true
        }
      ]
    },
    {
      "id": "proof",
      "type": "image_attachments",
      "title": "Proof",
      "columns": 2,
      "slots": [
        {
          "key": "bill",
          "label": "Ticket / Invoice",
          "accept": "image/*,application/pdf",
          "maxSizeMb": 5,
          "maps_to": "invoice_attachment"
        }
      ]
    }
  ]
}

{
  "templateId": "electricity-bill",
  "templateVersion": 1,
  "title": "Electricity Bill",
  "description_template": "Electricity – {premises} ({consumer_no}) for {billing_month}, {service_provider}[[, {units_consumed} units]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Bill",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "service_provider",
          "label": "Electricity Board",
          "type": "text",
          "required": true,
          "default": "BESCOM"
        },
        {
          "key": "consumer_no",
          "label": "Consumer / RR No.",
          "type": "text",
          "required": true
        },
        {
          "key": "premises",
          "label": "Premises",
          "type": "select",
          "options": [
            "Office",
            "Store Room",
            "Godown",
            "Other"
          ],
          "required": true
        },
        {
          "key": "billing_month",
          "label": "Billing Month",
          "type": "date",
          "required": true
        },
        {
          "key": "units_consumed",
          "label": "Units Consumed",
          "type": "number",
          "min": 0
        }
      ]
    },
    {
      "id": "proof",
      "type": "image_attachments",
      "title": "Proof",
      "columns": 2,
      "slots": [
        {
          "key": "bill",
          "label": "Bill",
          "accept": "image/*,application/pdf",
          "maxSizeMb": 5,
          "maps_to": "invoice_attachment"
        }
      ]
    }
  ]
}

