          "required": true
        },
        {
          "key": "payment_head",
          "label": "Payment Head",
          "type": "select",
          "options": [
            "GSTR-3B Liability",
            "GSTR-1",
            "Interest",
            "Late Fee",
            "Demand / Notice",
            "Other"
          ],
          "required": true
        },
        {
          "key": "period_month",
          "label": "For the Month",
          "type": "date",
          "required": true
        },
        {
          "key": "challan_or_arn",
          "label": "Challan / ARN",
          "type": "text"
        },
        {
          "key": "gstin",
          "label": "GSTIN",
          "type": "text"
        }
