    {
      "id": "proof",
      "type": "image_attachments",
      "title": "Proof",
      "columns": 2,
      "slots": [
        {
          "key": "bill",
          "label": "Challan",
          "accept": "image/*,application/pdf",
          "maxSizeMb": 5,
          "maps_to": "invoice_attachment"
        }
      ]
    }
  ]
}

{
  "templateId": "tds-payment",
  "templateVersion": 1,
  "title": "TDS Payment",
  "description_template": "TDS {tds_section}[[ @ {rate_percent}%]][[ ({deductee_class})]] for {period_month}[[, challan {challan_no}]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Payment",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "tds_section",
          "label": "TDS Section",
          "type": "select",
          "options": [
            "192 – Salary",
            "192B",
            "194C – Contract",
            "194I – Rent",
            "194J – Professional / Technical",
            "194Q – Purchase of Goods",
            "24Q – Return",
            "Other"
          ],
          "required": true
        },
        {
          "key": "deductee_class",
          "label": "Deductee Class",
          "type": "select",
          "options": [
            "Individual / HUF",
            "Company",
            "Not applicable"
          ],
          "required": true
        },
        {
          "key": "rate_percent",
          "label": "Rate (%)",
          "type": "number",
          "min": 0
        },
        {
          "key": "period_month",
          "label": "For the Month",
          "type": "date",
          "required": true
        },
        {
          "key": "challan_no",
          "label": "Challan / CIN",
          "type": "text"
        }
      ]
    },
    {
      "id": "proof",
      "type": "image_attachments",
      "title": "Proof",
      "columns": 2,
      "slots": [
        {
          "key": "bill",
          "label": "Challan",
          "accept": "image/*,application/pdf",
          "maxSizeMb": 5,
          "maps_to": "invoice_attachment"
        }
      ]
    }
  ]
}

