{
  "templateId": "payroll-payment",
  "templateVersion": 1,
  "title": "Payroll Payment",
  "description_template": "{payout_head} for {salary_month}[[ – {employee_name}]][[ via {payout_channel}]][[, {headcount} employee(s)]].",
  "sections": [
    {
      "id": "detail",
      "type": "fields",
      "title": "Payout",
      "layout": "grid",
      "columns": 2,
      "fields": [
        {
          "key": "payout_head",
          "label": "Payout Head",
          "type": "select",
          "options": [
            "Monthly Salary",
            "Advance Salary",
            "Full & Final Settlement",
            "PF (EPFO)",
            "ESI",
            "Professional Tax",
            "Employee Reimbursement",
            "Bonus / Incentive"
          ],
          "required": true
        },
        {
          "key": "salary_month",
          "label": "For the Month",
          "type": "date",
          "required": true
        },
        {
          "key": "employee_name",
          "label": "Employee",
          "type": "text"
        },
        {
          "key": "payout_channel",
          "label": "Channel",
          "type": "select",
          "options": [
            "Razorpay Payroll",
            "Bank Transfer",
            "Portal (EPFO / Treasury)",
            "Cash"
          ]
        },
        {
          "key": "headcount",
          "label": "No. of Employees",
          "type": "number",
          "min": 1
        }
      ]
    },
    {
      "id": "proof",
      "type": "image_attachments",
      "title": "Proof",
      "columns": 2,
      "slots": [
        {
          "key": "bill",
          "label": "Statement / Challan",
          "accept": "image/*,application/pdf",
          "maxSizeMb": 5,
          "maps_to": "invoice_attachment"
        }
      ]
